			aCEErrorCollection["181"] = new MessageError(errorCode: "181", shortDesc: "Conveyance Name Missing", narrative: "For ocean shipments, a conveyance name is required in the 20 record, pos 21-40. If the name is omitted, this error will result.");
			aCEErrorCollection["182"] = new MessageError(errorCode: "182", shortDesc: "Bnd Waiver Reason Not Allowed-Ent Type", narrative: "Bond waiver reason codes are only valid for specific entry types. Usage Note 'i)' in the ACE ABI CATAIR specifies the conditions and entry types that permit a request for a bond waiver (10 record, pos 38). If the entry type does not permit a bond waiver, a bond waiver reason code is similarly not permitted. If one is transmitted in the 10 record, pos 62-64, this error will result.");
			aCEErrorCollection["183"] = new MessageError(errorCode: "183", shortDesc: "Manifest Detail Required for MOT", narrative: "If the MOT in the 10 record, pos 36-37 is ocean/rail/air, an appropriate bill of lading, air waybill, rail bill, etc is required to be reported in the 23 record. If that data is omitted, this error will result.");
			aCEErrorCollection["184"] = new MessageError(errorCode: "184", shortDesc: "Manifest Detail Not Allowed W/O MOT", narrative: "If an acceptable MOT (see Table 3 of the ACE CATAIR) is not reported in the 10 record, manifest detail information is not allowed to be reported in the 23 record.");
			aCEErrorCollection["186"] = new MessageError(errorCode: "186", shortDesc: "Mnfst Component Typ Must Be I, H, M, or S", narrative: "The manifest component type is transmitted in the 23 record, pos 3. Only four alpha characters are authorized for this field. If any character other than I, M, H, or S is transmitted, this error will result.");
			aCEErrorCollection["187"] = new MessageError(errorCode: "187", shortDesc: "Mfst Components Out of Seq or Dup", narrative: "A manifest component cannot be repeated with the same manifest component grouping of a 22 record plus up to 4 23 records. (cannot report the same bill number or the same inbond number more than once). If the component is duplicated, this error will result. Also, the sequence of data elements must be reported per note 1 for the 23 record.");
			aCEErrorCollection["188"] = new MessageError(errorCode: "188", shortDesc: "Unlad DP Cannot = Entry DP for Inbond", narrative: "If the 23 record reports an inbond number (code 'I' in pos 3), the unlading port (20 record, pos 7-10) cannot be the same as the port of entry (10 record, pos 18-21).");
			aCEErrorCollection["189"] = new MessageError(errorCode: "189", shortDesc: "In-Bnd/Trn Date Not a Known Date", narrative: "The inbond date is transmitted in the 20 record, pos 52-57. If it is not in MMDDYY format and represents a valid date on the calendar, this error will result.");
			aCEErrorCollection["190"] = new MessageError(errorCode: "190", shortDesc: "Import Date Cannot Be } In-Bnd/Trn Date", narrative: "The import date is transmitted in the 11 record, pos 48-53 After the export date, it must be the earliest date reported of all the dates transmitted in the summary. If the inbond date, for example, is earlier than the import date, this error will result.");
			aCEErrorCollection["191"] = new MessageError(errorCode: "191", shortDesc: "In-Bnd/Trn Date Cannot Be } Entry Date", narrative: "The inbond date is transmitted in the 20 record, pos 52-57. This date cannot be later than the estimated entry date reported in the 11 record.");
			aCEErrorCollection["192"] = new MessageError(errorCode: "192", shortDesc: "In-Bnd/Trn Dt Cannot Be } 2 Yrs In Past", narrative: "The inbond date reported in the 20 record, pos 52-57, cannot be more than 2 years earlier than the transmission date of the AE to CBP.");
			aCEErrorCollection["193"] = new MessageError(errorCode: "193", shortDesc: "Multiple Continuous Bonds Not Allowed", narrative: "If the ACE entry has a 31 record with bond type 8, a second 31 record, if transmitted, cannot use bond type 8 again.");
			aCEErrorCollection["194"] = new MessageError(errorCode: "194", shortDesc: "Dsgntd Exam Site Unknown", narrative: "The DES is transmitted in the 20 record, pos 48-51. This field must be a valid U.S. CBP port code, listed in Sched K. If a port code in this field is not a valid Sch K code, this error will result.");
			aCEErrorCollection["195"] = new MessageError(errorCode: "195", shortDesc: "Dsgntd Exam Site Not Allowed/Ent Conflct", narrative: "If the selectivity record shows a designated exam site but the DES transmitted in the entry summary does not match the one on file, this error will result.");
			aCEErrorCollection["196"] = new MessageError(errorCode: "196", shortDesc: "Dsgntd Exam Site Not Allowed-Not RLF", narrative: "The filer has transmitted a designated exam site in the 20 record, pos 48-51. If the entry summary is not an RLF entry summary, this error will occur.");
			aCEErrorCollection["197"] = new MessageError(errorCode: "197", shortDesc: "Payment Type Code Unknown", narrative: "Valid payment type codes, 10 record, pos 51, are 1 through 8 as of Jan 2013. Any other code in this field will generate this error.");
			aCEErrorCollection["198"] = new MessageError(errorCode: "198", shortDesc: "Initial Pay Typ Cannot Be Indivd Payment", narrative: "ACE entry summaries must be first transmitted with payment type 2,3, 5, 6, 7, or 8. If payment type 1 is transmitted on the first AE, this error will result.");
			aCEErrorCollection["199"] = new MessageError(errorCode: "199", shortDesc: "Prelim Stmt Date Not Allowed", narrative: "If the payment type indicator in the 10 record, pos 51 is a '1', then the payment date field, pos 52-57, must be blank. If a payment date is included in this field with a payment type code of '1', this error will result.");
			aCEErrorCollection["200"] = new MessageError(errorCode: "200", shortDesc: "Periodic Stmt Month Not Allowed", narrative: "If the payment type indicator in the 10 record, pos 51 is other than 6, 7, or 8, the payment month field, pos 58-59 of the 10 record must be blank. If any data is transmitted in this field, this error will result.");
			aCEErrorCollection["201"] = new MessageError(errorCode: "201", shortDesc: "Stmt Client Branch Not Allowed", narrative: "If the 'branch' indicator on the filer's ABE record is not set to 'y', inclusion of a branch indicator in the 10 record, pos 60-61, will cause this error. ACE uses the port code in the B record to make this determination.");
			aCEErrorCollection["202"] = new MessageError(errorCode: "202", shortDesc: "Prelim Stmt Date Missing", narrative: "If the filer transmits a payment type other than 1 in the 10 record, pos 51, a statement print date is required in pos 52-57. If that date is omitted, this error will result.");
			aCEErrorCollection["203"] = new MessageError(errorCode: "203", shortDesc: "Prelim Stmt Date Not a Known Date", narrative: "The preliminary statement date is transmitted in mmddyy format. Any other format will cause this error.");
			aCEErrorCollection["204"] = new MessageError(errorCode: "204", shortDesc: "Prelim Stmt Date is Sat, Sun, or Hol", narrative: "The statement print date, transmitted in the 10 record, pos 52-57, cannot be on a Saturday, Sunday or designated federal holiday. Local holidays (Mardi Gras in 2002) will also generate this error.");
			aCEErrorCollection["205"] = new MessageError(errorCode: "205", shortDesc: "Prelim Stmt Date Must be in Future", narrative: "The preliminary payment print date, transmitted in the 10 record, pos 52-57, must be at least one business day in the future. If the date is in the past or equal to the transmission date of the summary, this error will result.");
			aCEErrorCollection["206"] = new MessageError(errorCode: "206", shortDesc: "Prelim Stmt Date } 90 Days in Future", narrative: "The statement print date, transmitted in the 10 record, pos 52-57, cannot be more than 90 days in the future, as compared to the system transmission date.");
			aCEErrorCollection["207"] = new MessageError(errorCode: "207", shortDesc: "Statement Processing Not Authorized", narrative: "The filer's ACS ABE record has not been updated to operational status for statement processing.");
			aCEErrorCollection["208"] = new MessageError(errorCode: "208", shortDesc: "Periodic Stmt Requires Continuous Bond", narrative: "If payment 6, 7 or 8 is transmitted in the 10 record, pos 51, a continuous bond must on file for the importer and bond type 8 must be transmitted in the 10 record, pos 38.");
			aCEErrorCollection["209"] = new MessageError(errorCode: "209", shortDesc: "Periodic Statement Requires ACE Filer", narrative: "10 rec, pos 51, contains the payment type indicator. If type 6, 7, or 8 is used, the filer (broker or importer) must be a PMS participant.");
			aCEErrorCollection["210"] = new MessageError(errorCode: "210", shortDesc: "Periodic Stmt Requires ACE Importer", narrative: "10 rec, pos 51, contains the payment type indicator. If type 6, 7, or 8 is used, the importer of record in the 11 rec, pos 3-14, must be a PMS participant.");
			aCEErrorCollection["211"] = new MessageError(errorCode: "211", shortDesc: "Periodic Stmt Month Missing", narrative: "If a filer elects to use PMS for an AE submission, the requested payment month must be transmitted in pos 58-59 of the 10 record. If payment type 6, 7, or 8 is transmitted in pos 51, and no payment month is included, this error will result.");
			aCEErrorCollection["212"] = new MessageError(errorCode: "212", shortDesc: "Periodic Statement Month Unknown", narrative: "The month of statement payment for a PMS statement is transmitted in the 10 record, pois 58-59. That field must indicate '01' through '12'. Any other code in that field will generate this error.");
			aCEErrorCollection["213"] = new MessageError(errorCode: "213", shortDesc: "Periodic Stmt Month Too Far Into Future", narrative: "The periodic statement month is transmitted in the 10 record, pos 58-59. This field requires a two-numeric month indicator (01 through 12). The month selected can be no further into the future than two months following the month of the release.");
			aCEErrorCollection["214"] = new MessageError(errorCode: "214", shortDesc: "STB Amount Not Allowed for Bond Type", narrative: "f the filer indicates a continuous bond ('B' in pos 3 of the 31 record), the STB amount field (pos 19-28 of the 31 record) must be blank.");
			aCEErrorCollection["215"] = new MessageError(errorCode: "215", shortDesc: "Prelim Stmt Day } Periodic Stmt Day", narrative: "If the filer transmits a periodic statement print date that is after the date that the periodic monthly statement will generate for the statement month requested, this error will result.");
			aCEErrorCollection["216"] = new MessageError(errorCode: "216", shortDesc: "Prelim Stmt for Date Already Produced", narrative: "If the AE contains a statement print date (10 record, pos 52-57) that is equal to or earlier than the date of transmission of the AE, this error will result.");
			aCEErrorCollection["217"] = new MessageError(errorCode: "217", shortDesc: "Pymt Info Not Allwd - Post Pymnt Corrctn", narrative: "Once an ACE entry summary has been paid in via statement/ACH acceptance, a retransmission of the summary cannot reference any data in the statement payment fields (cannot use any payment type nor any date in the payment date field) This error will also occur if an ACE summary is rejected by CBP prior to the scheduled payment date.");
			aCEErrorCollection["218"] = new MessageError(errorCode: "218", shortDesc: "Estimated Entry Dt Cannot Be } Stmt Dt", narrative: "The estimated entry date is transmitted in the 11 record, pos 42-47. This date cannot be later than the statement print date, transmitted in the 10 record, pos 52-57.");
			aCEErrorCollection["219"] = new MessageError(errorCode: "219", shortDesc: "Stmt Client Branch Missing", narrative: "If the filer's ABE profile is set to 'Y' in the branch field, a branch indicator is always required in the 10 record, pos 60-61. If the branch indicator is omitted, this error will result.");
			aCEErrorCollection["220"] = new MessageError(errorCode: "220", shortDesc: "Elec Invoice Indicator Must Be Y", narrative: "The indicator that the filer is submitting an electronic entry is transmitted in the 10 record, pos 41. The only acceptable value for this field is a 'Y'. Any other character will cause this error.");
			aCEErrorCollection["221"] = new MessageError(errorCode: "221", shortDesc: "RLF Requires Elec Invoice", narrative: "An RLF entry must include a 42 record designating the invoice supplier MID and invoice number being provided. If the 42 record is omitted, this error will result. ACE will examine the B record for the RLF preparer port and filer data, the RLF indicator, and the 10 record, pos 41 for the Electronic Invoice Indicator. If one of these three elements are missing, this error will result, even if the 42 record is transmitted.");
			aCEErrorCollection["222"] = new MessageError(errorCode: "222", shortDesc: "Elec Invoice Requires Summary on Stmt", narrative: "An ACE entry summary which reports a Y in pos 41 of the 10 record, indicating an electronic entry, must be scheduled for statement (ACH) processing in pos 51 of the 10 record. If a '1' is transmitted in pos 51 for such an entry, this error will result. If the entry is a PSC filing, the requirement for an electronic entry to be scheduled for ACH is waived and position 51 of the 10 record must be blank.");
			aCEErrorCollection["223"] = new MessageError(errorCode: "223", shortDesc: "Cont Superseded Bond Ind Not Allowed", narrative: "If a filer wishes to report a superseding continuous bond, the indicator to be transmitted for this purpose is 'Y' in pos 5 of the 31 record. Any other character in this field will generate this reject message.");
			aCEErrorCollection["224"] = new MessageError(errorCode: "224", shortDesc: "Elec Invoice Requires Continuous Bond", narrative: "If an AE has a 'y' in pos 41 of the 10 record, indicating an electronic entry, a continuous bond must be obligated. If the 10 record, pos 38, does not show '8', this error will result.");
			aCEErrorCollection["225"] = new MessageError(errorCode: "225", shortDesc: "Elec Invoice Not Allowed - Ent D/P Not AII", narrative: "The transmitted port of entry is not eligible for EIP or RLF processing.");
			aCEErrorCollection["226"] = new MessageError(errorCode: "226", shortDesc: "Elec Invoice Not Allowed - Filer Not AII", narrative: "The filer's ABE record was not set to operational for AII prior to the transmission of an AE with 'y' in pos 41 of the 10 record.");
			aCEErrorCollection["227"] = new MessageError(errorCode: "227", shortDesc: "Correction Requires Elec Invoice", narrative: "If an ACE entry summary which has been accepted by CBP is an electronic entry, any further transmissions of that entry number must include a 42 record with an invoice number. If the AE is transmitted without a 42 record, this error will result.");
			aCEErrorCollection["228"] = new MessageError(errorCode: "228", shortDesc: "Consolidated Summ Ind Must Be Y", narrative: "A consolidated entry summary is indicated by an indicator in the 10 record, pos 42. The only acceptable value for this field is a 'Y'. Any other indicator will cause this reject.");
			aCEErrorCollection["232"] = new MessageError(errorCode: "232", shortDesc: "Release Detail Missing", narrative: "If the AE has a 'Y' in pos 42 of the 10 record, indicating that this summary is a consolidated summary, there must be at least one 32 record listing at least two entry numbers.");
			aCEErrorCollection["233"] = new MessageError(errorCode: "233", shortDesc: "Release Detail Not Allowed", narrative: "If a 32 record is included in an entry summary and pos 42 of the 10 record is not transmitted with a 'Y', this error will result.");
			aCEErrorCollection["234"] = new MessageError(errorCode: "234", shortDesc: "Rlse Entry Filer Code Missing", narrative: "A consolidated entry is reported in the 32 record. The filer code of the entry is required for each entry number reported. If the filer code is omitted, this error will result.");
			aCEErrorCollection["235"] = new MessageError(errorCode: "235", shortDesc: "Rlse Entry Number Missing", narrative: "Entry numbers reported as part of a consolidated summary are listed in the 32 record. The filer code of each release must be accompanied by the actual entry number. If a release filer code is transmitted without the associated entry number, this error will result.");
			aCEErrorCollection["236"] = new MessageError(errorCode: "236", shortDesc: "Rlse Entry Filer Not = Cnsldtd Filer", narrative: "Released entries reported in the 32 record must have the same filer code as the filer of the consolidated summary. If a different filer code is reported in any of the 'filer code' fields in the 32 record, this error will result.");
			aCEErrorCollection["237"] = new MessageError(errorCode: "237", shortDesc: "Rlse Entry Not Previously Established", narrative: "If a consolidated entry is indicated in the 10 record, pos 42, any entry numbers listed in the 32 record must be on file in ACE has having a release associated with that entry number(s). If there is no release on file for the listed entry number(s), this error will result.");
			aCEErrorCollection["239"] = new MessageError(errorCode: "239", shortDesc: "Rlse Entry Nbr = To Cnsldtd Ent Nbr", narrative: "Consolidated entries must use a different entry number from any of the consolidated releases reported in the 32 record. If the entry numbers are the same, this error will result.");
			aCEErrorCollection["240"] = new MessageError(errorCode: "240", shortDesc: "Bond Amount Cannot Be $0", narrative: "The bond amount for a single transaction bond is transmitted in the 31 record, pos 9-18. That field cannot reflect zero as the bond amount.");
