			aCEErrorCollection["248"] = new MessageError(errorCode: "248", shortDesc: "Acct Class Code Missing", narrative: "If a fee is reported at the header level for the AE input (informal entry fee, for example), in a 34 record, the 89 record for the same accounting code is required. If the 89 record omits the code used in the 34 record, this error will result.");
			aCEErrorCollection["249"] = new MessageError(errorCode: "249", shortDesc: "Acct Class Code Unknown", narrative: "Classification codes for fees are reported in the appropriate record (34, 62, and 89). The class code must be a valid, pre-established code. If a code that is not currently on file is used in one of these records, this error will result.");
			aCEErrorCollection["250"] = new MessageError(errorCode: "250", shortDesc: "Acct Class Code Not Allowed", narrative: "Certain fee class codes must be reported in the 62 record and others are reported in the 34 record. If a code that is reportable only in the 34 record is reported in a 62 record, or vice versa, this error will result. Further, if the same class code is reported twice (identical 62 records, e.g.) this error will also be generated. Also, if the fee is not reportable due to exemptions that exist (LDDC, NAFTA country), this error will be issued if the fee is reported.");
			aCEErrorCollection["252"] = new MessageError(errorCode: "252", shortDesc: "User Fee Amount Missing", narrative: "If a header level (34 record) fee code is transmitted, but the fee amount is left blank, this error will result.");
			aCEErrorCollection["253"] = new MessageError(errorCode: "253", shortDesc: "User Fee Amount Contains Non-Numerics", narrative: "If spaces are sent in a user fee field, this error will result. Only numeric characters are allowed.");
			aCEErrorCollection["254"] = new MessageError(errorCode: "254", shortDesc: "Duplicate Account Class Encountered", narrative: "The same accounting class code (for fees) cannot appear in the 89 record more than once. In the AE that caused this reject, the filer sent 000 in the entire record, so ACE read each set of 000 that appeared in the 2nd and subsequent class code fields(pos 17-19,31-33, etc) as a duplicate fee class code.");
			aCEErrorCollection["255"] = new MessageError(errorCode: "255", shortDesc: "Consignee Nbr missing", narrative: "For all 01 and 03 entries, an ultimate consignee must be transmitted in the 11 record, pos 15-26. If this element is left blank, this error will result. The consignee number is not required for an informal entry, type 11.");
			aCEErrorCollection["258"] = new MessageError(errorCode: "258", shortDesc: "Manifest Qty Must Be } Zero", narrative: "If the field for quantity is completed in the 22 record, pos 3-10, it must be a whole number greater than zero.");
			aCEErrorCollection["259"] = new MessageError(errorCode: "259", shortDesc: "Manifest Qty Missing", narrative: "For an MOT that requires manifest quantity reporting, the 22 record, pos 3-10, must reflect a quantity (greater than zero). If the field is left blank, this error will result.");
