			aCEErrorCollection["261"] = new MessageError(errorCode: "261", shortDesc: "In-Bnd/Trn Dt Req'd with In-Bnd/Trn Nbr", narrative: "If the 23 record reports an inbond number (code 'I' in pos 3), an inbond origination date is required. This is transmitted in the 20 record, pos 52-57. If the date is omitted, this error will result.");
