			aCEErrorCollection["266"] = new MessageError(errorCode: "266", shortDesc: "Bond Designation Must Be A or B", narrative: "The 31 record transmits bond information, including whether the bond is a basic bond ('b') for the entry or an additional bond ('a') for AD/CVD requirements. Any code besides 'a' or 'b' will reject with this error.");
			aCEErrorCollection["267"] = new MessageError(errorCode: "267", shortDesc: "Continuous Bond Must Be for Basic Use", narrative: "If a continuous bond is reported in the 31 record, its bond designation type code must be 'B', for basic. A continuous bond cannot be reported as an additional bond, code 'A'.");
			aCEErrorCollection["268"] = new MessageError(errorCode: "268", shortDesc: "STB Must be Designated Additional", narrative: "If the filer elects to report two 31 records, one must be designated for additional bond coverage (code A in pos 4). If two 31 records are transmitted with code 'B' in pos 4, this error will result.");
			aCEErrorCollection["269"] = new MessageError(errorCode: "269", shortDesc: "Basic Bond Missing", narrative: "For entry types which require a bond, at least one 31 record is required and must reference 'bond designation type code' B. If only one 31 record transmitted in the AE and does not reference code 'B', this error will result.");
