			aCEErrorCollection["275"] = new MessageError(errorCode: "275", shortDesc: "Accelerated Liq Req Ind Unknown", narrative: "A request for accelerated liquidation on a PSC can only be a 'Y'. Any other character in this field (10 record, pos 66) will cause this reject.");
			aCEErrorCollection["276"] = new MessageError(errorCode: "276", shortDesc: "Accelerated Liq Req Ind Not Allowed", narrative: "A conventional ACE entry summary cannot have any data in position 66 of the 10 record. This is reserved for use in a PSC.");
			aCEErrorCollection["277"] = new MessageError(errorCode: "277", shortDesc: "PSC Filing Explanation Not Allowed", narrative: "A conventional ACE entry summary cannot include a 36-record (the PSC filing explanation). This is reserved for use in a PSC submission.");
			aCEErrorCollection["278"] = new MessageError(errorCode: "278", shortDesc: "Header PSC Code Unknown", narrative: "A PSC was transmitted with a header reason code not found in Table 14 of the ACE Entry Summary Create/Update chapter of the ACE CATAIR.");
			aCEErrorCollection["279"] = new MessageError(errorCode: "279", shortDesc: "Hdr PSC Code Duplicate Encountered", narrative: "A PSC filing has reported two or more identical header reason codes.");
