			aCEErrorCollection["286"] = new MessageError(errorCode: "286", shortDesc: "IOR Change Not Allowed for PSC", narrative: "If a change to the Importer of Record (IOR) is needed. Prior to PSC filing, the trade must send a request to change the IOR to CBP with CF 3347. See ACE Entry Summary Business Rules and Process Document for additional guidance.");
			aCEErrorCollection["287"] = new MessageError(errorCode: "287", shortDesc: "PSC Filing Explanation Missing", narrative: "A PSC was transmitted without an explanation for the change being included via the 36 record.");
			aCEErrorCollection["400"] = new MessageError(errorCode: "400", shortDesc: "Line Item(s) Missing", narrative: "If the summary action filing request code in the 10 record, pos 3 is 'a' or 'r', line item data is required, starting in the 40 record. If no line item data is provided, this error will result.");
