			aCEErrorCollection["A22"] = new MessageError(errorCode: "A22", shortDesc: "Non-contiguous item found in grouping", narrative: "This error will result if a record with multiple fields for quantity (50 record) are not used in sequential order..That is, if there are two quantities to report, they must occupy the first two quantity fields. If field one is used, and the 2nd quantity is reported in field 3, this is the error that will result. The AX output message will identify the record with the error.");
			aCEErrorCollection["A23"] = new MessageError(errorCode: "A23", shortDesc: "Loop Exceeded- Article Parties", narrative: "If the current version of AE permits a finite number of records (in this case, the number of parties that can be included in the 47 record in version A2.2), and more than the allowed number of such records are transmitted, this error will result.");
			aCEErrorCollection["A24"] = new MessageError(errorCode: "A24", shortDesc: "Loop Exceeded", narrative: "This error can apply to any input record that is repeatable. If the maximum number of identical records is exceeded (check the ACE ABI CATAIR for each record's allowable maximum number of iterations), this error will result.");
			aCEErrorCollection["B01"] = new MessageError(errorCode: "B01", shortDesc: "Action Request Code Missing", narrative: "The action (add, replace or delete) code is transmitted in the 10 record, pos 3. If the code field is blank, this error will result.");
