			aCEErrorCollection["B03"] = new MessageError(errorCode: "B03", shortDesc: "District/Port of Entry Missing", narrative: "The DDPP is required to be transmitted in every AE transaction. It is transmitted in the 10 record, pos 18-21. If this element is missing, this error will result.");
			aCEErrorCollection["B04"] = new MessageError(errorCode: "B04", shortDesc: "District/Port of Entry Unknown", narrative: "The district port of entry is transmitted in the 10 record, pos 18-21. The field cannot be left blank and must use a valid CBP entry port code. If either of these conditions is not met, this error will result.");
