			aCEErrorCollection["B24"] = new MessageError(errorCode: "B24", shortDesc: "Extraneous Data Not Allowed - Delete", narrative: "The filer has sent a complete AE input transaction for a delete action code in the 10 record. If a delete of an AE entry summary is being requested, only the elements listed as Mandatory for all 10 record actions can be transmitted.");
