			aCEErrorCollection["B30"] = new MessageError(errorCode: "B30", shortDesc: "Entry Summary Has Been Liquidated", narrative: "If an ACE Entry summary has been scheduled for liquidation, a retransmission of the AE is not permitted. This error will result. If an ACE Entry summary has been scheduled for liquidation, a transmission of the CW is not permitted. After payment, unresolved census warnings can be resolved by transmitting a PSC with the proper census override codes.");
