			aCEErrorCollection["B63"] = new MessageError(errorCode: "B63", shortDesc: "Cargo Cert Ignored/Process Already Done", narrative: "An ACE entry summary that includes a cargo certification request in pos 40 of the 10 record and for which cargo selectivity has already been performed will receive this error message. This is scheduled to be implemented on Jan 12, 2013.");
